import { DayPlan, Drill, Phase } from "../learning-plan"
import { mcq, fill, fix, transform, write, speak } from "../drill-factory"

function mk(w:number,d:number,title:string,focus:string,theory:string,phases:Phase[]):DayPlan{
  return{week:w,day:d,title,focus,theory,phases}
}
function gp(prefix:string,fn:(pid:string,pn:number)=>Phase):Phase[]{
  return Array.from({length:10},(_,i)=>fn(`${prefix}p${i+1}`,i+1))
}

/* ── Week 3 · Day 1 ── Professional Emails ──────────────────────────────── */

const W3D1=mk(3,1,
  "Professional Emails",
  "Write clear, direct, appropriately formal emails for IT workplace scenarios.",
  "Email yang baik itu seperti peta — pembacanya langsung tahu harus ke mana dan apa yang diharapkan dari mereka.\n\n**Struktur email**: Baris subjek → Salam → Konteks (1 kalimat) → Permintaan/Informasi → Langkah selanjutnya → Penutup.\n\n**Baris subjek**: Spesifik dan mudah dipindai. 'API timeout issue on prod — action needed', BUKAN cuma 'Problem' atau 'Hi'.\n\n**Pilihan tingkat formalitas**:\n- Terlalu santai: 'Hey, can you fix this?' (tidak cocok untuk klien atau atasan)\n- Terlalu kaku: 'I am writing to enquire as to whether it would be possible…' (bertele-tele)\n- Profesional: 'Could you please review the attached report by Friday?' (jelas, sopan, ada deadline)\n\n**Email permintaan**: Jelaskan konteks → buat permintaan → tentukan deadline → tawarkan bantuan.\n**Email status**: Apa yang sudah selesai → apa yang sedang berjalan → hambatan → ETA.\n**Email eskalasi**: Dampak ke bisnis → timeline kejadian → apa yang sudah dicoba → apa yang dibutuhkan.\n\n**Kesalahan umum di email IT**:\n- Permintaannya disembunyikan di paragraf ke-3 (pembaca harus baca sampai habis dulu)\n- Tidak ada deadline yang spesifik\n- Satu paragraf panjang seperti tembok teks\n- Baris subjek hanya 'Question' atau 'Hi'",
  gp("w3d1",(pid,pn)=>{
    const TITLES=["Subject Line Quality MCQ","Opening & Closing Phrases","Request vs. Statement Tone","Identify Email Type","Spot the Error","Fill — Email Phrases","Write a Request Email","Write a Status Update Email","Write an Escalation Email","Speak: Summarise an Email"]
    const OBJS=["Evaluate subject lines for clarity and specificity.","Choose appropriate professional openings and closings.","Distinguish polite request from blunt statement.","Identify whether an email is a request, status, or escalation.","Spot inappropriate register, grammar, or structure in emails.","Complete professional email phrases with correct words.","Write a clear, well-structured request email.","Write a concise status update email with ETA and blockers.","Write a professional escalation email with impact statement.","Summarise an email situation aloud in professional English."]
    const m=[
      mcq(`${pid}_01`,"Which subject line is most professional for a production incident?",["a:URGENT","b:Problem with the server","c:Production outage — auth service down since 14:30 UTC","d:Hey check this out"],"c","Subject line harus spesifik: nama service, statusnya apa, dan sejak kapan. Pembaca harus langsung tahu apa yang terjadi sebelum membuka email."),
      mcq(`${pid}_02`,"Which opening is most appropriate for a formal client email?",["a:Hey Sarah,","b:Hi,","c:Dear Ms Chen,","d:Yo Sarah,"],"c","Untuk email formal ke klien, gunakan 'Dear [Nama],' dengan nama belakang. 'Hi' terlalu santai untuk klien yang belum akrab."),
      mcq(`${pid}_03`,"Which is the most professional way to make a request?",["a:Fix the bug by tomorrow.","b:Could you please review the PR by end of day Friday?","c:You need to check this.","d:I was wondering if maybe you could take a look?"],"b","Permintaan yang baik: sopan (could you please), spesifik (review the PR), dan ada deadlinenya (by end of day Friday). Pilihan D terlalu meragukan dan bertele-tele."),
      mcq(`${pid}_04`,"'I am writing to bring to your attention an issue of some significance regarding the aforementioned system' — what is wrong?",["a:Too short","b:Too casual","c:Too formal and indirect — bury the point","d:Nothing is wrong"],"c","Kalimat ini terlalu bertele-tele dan memendam inti pesan. Langsung saja: 'There is a critical issue with [sistem].' Pembaca tidak perlu membaca setengah paragraf dulu untuk tahu apa yang terjadi."),
      mcq(`${pid}_05`,"Which closing is appropriate for a formal email to a client?",["a:Cheers,","b:Best regards,","c:Later,","d:Talk soon,"],"b","'Best regards,' adalah penutup standar untuk email formal ke klien. 'Cheers' dan 'Talk soon' terlalu santai untuk konteks bisnis."),
      mcq(`${pid}_06`,"An email about deployment status should lead with:",["a:Your company background","b:A detailed explanation of the codebase","c:Current status, what is done, and the next ETA","d:A list of all team members involved"],"c","Email status: mulai dengan status sekarang (selesai/berjalan/terhambat), apa yang sudah selesai, dan kapan ETA berikutnya. Pembaca ingin tahu statusnya dulu, bukan latar belakang."),
      mcq(`${pid}_07`,"Which is the correct structure for a request email?",["a:Request → Context → Closing","b:Context → Request → Deadline → Offer to help","c:Background → History → Background → Request","d:Subject → Body → Request → Subject"],"b","Struktur email permintaan terbaik: konteks singkat → permintaan yang jelas → deadline → tawarkan bantuan. Jangan kubur permintaan di akhir!"),
      mcq(`${pid}_08`,"'Please advise.' at the end of an email sounds:",["a:Clear and professional","b:Passive-aggressive or vague in many contexts","c:Too casual","d:Too formal"],"b","'Please advise.' terlalu samar dan bisa terdengar pasif-agresif. Lebih baik spesifik: 'Could you let me know your decision by Thursday?' — pembaca tahu persis apa yang diharapkan dari mereka."),
      mcq(`${pid}_09`,"For an escalation email, which element must come first?",["a:A long history of the problem","b:A complaint about the team","c:The impact of the issue on the business","d:A request for a meeting"],"c","Email eskalasi harus dimulai dengan DAMPAK ke bisnis — ini yang membuat orang langsung merespons. Setelah itu baru jelaskan kronologi dan apa yang dibutuhkan."),
      mcq(`${pid}_10`,"'As per my last email' is problematic because:",["a:It is too casual","b:It has a passive-aggressive tone in many workplaces","c:It is grammatically incorrect","d:It is too long"],"b","'As per my last email' sering terdengar pasif-agresif (seperti mengungkit atau menyindir). Lebih baik: 'To recap from my previous message' atau langsung referensikan emailnya secara netral."),
      mcq(`${pid}_11`,"Which is the clearest way to communicate a blocker?",["a:Things are a bit slow on our end.","b:There are some issues.","c:We are blocked on the database migration approval — needed by Wednesday to meet the sprint goal.","d:Could you perhaps look into this when you get a chance?"],"c","Blocker yang baik harus spesifik: apa yang terhambat, apa yang dibutuhkan, dan kapan batasnya (supaya sprint goal tidak terganggu). Pilihan A dan B terlalu samar untuk ditindaklanjuti."),
      mcq(`${pid}_12`,"'FYI' in a professional email subject line is:",["a:Always inappropriate","b:Fine for internal informational emails, never for client emails","c:A strong opener","d:The same as 'Action required'"],"b","'FYI' (For Your Information) bisa dipakai untuk email informasi internal ke sesama tim. Tapi untuk klien atau email eksternal, terlalu santai — gunakan subjek yang lebih deskriptif."),
      mcq(`${pid}_13`,"Which phrase best replaces 'ASAP' in a formal email?",["a:Immediately","b:Very soon","c:By [specific date/time], if possible","d:Yesterday"],"c","'ASAP' tidak jelas — seberapa cepat itu? Selalu berikan deadline yang spesifik: 'by Friday 5 PM' atau 'by EOD today'. Ini menghindari kesalahpahaman."),
      mcq(`${pid}_14`,"An email that starts 'Just wanted to check in…' is:",["a:Professional and warm","b:Appropriately formal","c:Too hedging — use a direct opener","d:Perfect for all contexts"],"c","'Just wanted to check in' terlalu meragukan dan membuang-buang kalimat pertama. Langsung saja: 'I am following up on [topik] from [tanggal].' Pembaca langsung tahu konteksnya."),
      mcq(`${pid}_15`,"Which is the correct way to CC someone relevant to an email?",["a:Always CC everyone on the team","b:CC only those who need to be aware or may need to take action","c:BCC everyone for privacy","d:Never CC anyone"],"b","CC hanya orang yang benar-benar perlu tahu atau perlu mengambil tindakan. Terlalu banyak CC = noise, dan orang cenderung abaikan email dengan banyak penerima."),
      mcq(`${pid}_16`,"'Please find attached the report.' vs 'I've attached the report.' — in a formal context:",["a:Both are fine; they are interchangeable","b:'Please find attached' is correct; the other is too casual","c:'I've attached' is better; 'please find attached' is outdated","d:'Please find attached' is grammatically incorrect"],"c","'I've attached the report.' lebih alami dan modern. 'Please find attached' sudah kuno (dated) meskipun tidak salah. Di dunia IT modern, langsung dan sederhana lebih disukai."),
      mcq(`${pid}_17`,"What should you do if an email thread is getting too long to follow?",["a:Keep replying to the same thread indefinitely","b:Start a fresh email with a clear summary of the current status","c:Delete old messages from the thread","d:Print the thread and scan it"],"b","Thread yang terlalu panjang membingungkan. Mulai email baru dengan rangkuman status terkini — ini lebih efisien dan memastikan semua pihak punya informasi yang sama."),
      mcq(`${pid}_18`,"Which opening is most appropriate for a follow-up email (no reply after 3 days)?",["a:Why haven't you replied?","b:I'm writing again because you ignored my email.","c:I am following up on my email from [date] regarding [topic]. Could you please advise on the timeline?","d:Just checking in!"],"c","Follow-up profesional: referensikan email sebelumnya dengan tanggal dan topik, lalu ajukan pertanyaan spesifik. Jangan menyalahkan atau menekan penerima."),
      mcq(`${pid}_19`,"'The bug was caused by John.' vs 'The bug was caused by an incorrect configuration.' — which is better in a client-facing incident report?",["a:The first — be transparent about who caused it","b:The second — focus on the technical cause, not individuals","c:Neither — don't explain the cause","d:Both are equally appropriate"],"b","Laporan yang menghadap klien harus fokus pada penyebab TEKNIS, bukan siapa orangnya. Menyebut nama individu tidak profesional dan bisa merusak hubungan tim. Fokus pada sistem, bukan orang."),
      mcq(`${pid}_20`,"A good status email closing should:",["a:End with 'Let me know if you have any questions' only","b:Confirm next steps, ETA, and your availability","c:List every task completed","d:End with a motivational quote"],"b","Penutup email status yang baik: konfirmasi langkah berikutnya, kapan ETA-nya, dan ketersediaanmu. Pembaca tidak perlu menebak-nebak apa yang terjadi selanjutnya."),
      mcq(`${pid}_21`,"Which sentence is most direct and professional?",["a:I think maybe there could be some potential issues with the plan.","b:There are three issues with the proposed plan that need to be resolved before we proceed.","c:Honestly, the plan is a bit of a mess.","d:The plan might have issues, possibly."],"b","Kalimat yang baik: langsung, spesifik, dan dapat ditindaklanjuti. Pilihan B menyebutkan jumlah masalah (tiga) dan apa yang perlu dilakukan (diselesaikan sebelum lanjut). Pilihan A dan D terlalu meragukan."),
      mcq(`${pid}_22`,"'Hope this email finds you well.' should be used:",["a:In all professional emails","b:Only when you genuinely don't know the person and are unsure of their context","c:Never — it is filler and wastes the reader's time","d:Only in international emails"],"c","Kalimat basa-basi seperti 'Hope this email finds you well' tidak menambah nilai apapun. Langsung saja ke inti pesan — waktu pembaca berharga."),
      mcq(`${pid}_23`,"When reporting that a deadline will be missed, you should:",["a:Wait until the last minute","b:Proactively notify stakeholders as soon as you know, with a revised ETA","c:Blame an external factor only","d:Skip the email and mention it verbally"],"b","Begitu tahu deadline akan terlewat, langsung beritahu pemangku kepentingan dengan ETA yang baru. Proaktif itu jauh lebih baik daripada menunggu sampai deadlinenya benar-benar terlewat."),
      mcq(`${pid}_24`,"Which is the most appropriate sign-off for an internal team email?",["a:Yours faithfully,","b:Kind regards,","c:With deepest respect,","d:Peace,"],"b","'Kind regards,' adalah penutup standar untuk email internal profesional. 'Yours faithfully' terlalu kaku (biasanya untuk surat resmi). 'Peace' terlalu santai."),
      mcq(`${pid}_25`,"An email about a release should include:",["a:Release version, what changed, any risks, and rollback plan if applicable","b:Only what changed","c:A full git diff","d:The full Jira backlog"],"a","Email rilis yang lengkap harus mencakup: versi rilis, apa yang berubah, risiko yang perlu diperhatikan, dan rencana rollback jika ada masalah. Ini standar komunikasi rilis yang profesional."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`Subject: Stuff\n\nHey team,\n\nJust FYI there's a problem. ASAP please fix. Thanks.`,`Subject: Production login failure — action needed\n\nHi team,\n\nThe login service is returning 500 errors affecting approximately 200 users. Could you please investigate and provide an update by 17:00 today?\n\nBest regards,\n[Name]`,"Clear subject, specific impact, request, deadline."))
      else if(pn<=7) drills.push(fill(id,`I am writing to ___ you that the deployment has been completed successfully. All services are ___ normally. No further action is ___ at this time.`,["inform","operating","required"],"Standard status-update email phrases."))
      else if(pn===8) drills.push(write(id,`Write a professional request email to your manager asking for an additional two days to complete a feature due to an unexpected dependency issue. Include: context, specific request, reason, revised timeline.`,120))
      else if(pn===9) drills.push(write(id,`Write a client escalation email: the staging environment has been down for 8 hours due to a third-party API issue. Include: impact, timeline, what you have tried, what you need from the client.`,150))
      else drills.push(speak(id,"Speak for 60 seconds: you just sent a status update email. Summarise it aloud to a colleague — what is done, what is in progress, what is blocked, and what is the ETA."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 3 · Day 2 ── Bug Reports & Incident Reports ───────────────────── */

const W3D2=mk(3,2,
  "Bug Reports & Incident Reports",
  "Write structured, precise bug and incident reports that engineers can act on immediately.",
  "Bug report yang baik seperti resep masakan — harus jelas langkah-langkahnya supaya orang lain bisa mereproduksi masalahnya dan memperbaikinya.\n\n**Struktur bug report**:\n1. **Judul**: [Komponen] [Perilaku yang salah] — singkat dan spesifik.\n2. **Lingkungan**: OS, browser, versi, konfigurasi.\n3. **Langkah untuk mereproduksi**: Bernomor, minimal, tepat — ditulis dengan kata perintah (Click, Enter, Press).\n4. **Hasil yang diharapkan**: Apa yang seharusnya terjadi.\n5. **Hasil aktual**: Apa yang sebenarnya terjadi (beserta pesan error).\n6. **Dampak**: Siapa yang terkena dampak, seberapa parah.\n7. **Bukti**: Log, screenshot, kode error HTTP.\n\n**Struktur incident report (post-mortem)**:\n1. **Ringkasan**: Satu kalimat — apa yang terjadi, kapan, berapa lama, dampaknya.\n2. **Timeline**: Urutan kejadian dengan timestamp yang akurat.\n3. **Akar masalah**: Penjelasan teknis (bukan menyalahkan orang).\n4. **Dampak**: Pengguna yang terkena, pelanggaran SLA, kerugian bisnis.\n5. **Penyelesaian**: Apa yang dilakukan untuk memperbaikinya.\n6. **Pencegahan**: Daftar tindakan nyata dengan penanggung jawab dan tanggal.\n\n**Ketepatan bahasa**: Pakai passive untuk fakta teknis ('The service **was restarted**'), past tense untuk urutan kejadian, present tense untuk kondisi saat ini.",
  gp("w3d2",(pid,pn)=>{
    const TITLES=["Bug Report Quality MCQ","Steps to Reproduce Language","Expected vs. Actual Result","Incident Summary Writing","Root Cause Language","Fill — Bug Report Fields","Fill — Incident Timeline","Write a Bug Report Title","Write a Complete Bug Report","Write an Incident Summary"]
    const OBJS=["Evaluate bug report quality for completeness and precision.","Write clear, reproducible steps using imperative verbs.","Distinguish 'expected' from 'actual' result precisely.","Write a one-sentence incident summary with all key facts.","Write a root cause analysis without blame language.","Complete standard bug/incident report field templates.","Write a chronological incident timeline with timestamps.","Write a specific, actionable bug report title.","Write a complete, well-structured bug report.","Write a professional post-mortem incident summary."]
    const m=[
      mcq(`${pid}_01`,"Which bug title is most actionable?",["a:Login broken","b:Bug in auth","c:Login form returns 500 error when password contains special characters","d:Please fix the login issue ASAP"],"c","Judul bug yang baik harus menjawab: komponen apa (login form), perilaku apa (returns 500 error), dan pemicunya apa (when password contains special characters). Pilihan A dan B terlalu samar."),
      mcq(`${pid}_02`,"'Steps to reproduce' should use:",["a:Past tense narrative","b:Numbered imperative steps: Click, Enter, Press","c:Future tense instructions","d:Passive voice throughout"],"b","Langkah-langkah reproduksi terbaik: bernomor, menggunakan kata perintah (Click, Enter, Press). Ini seperti resep masakan — harus bisa diikuti siapapun untuk mendapatkan hasil yang sama."),
      mcq(`${pid}_03`,"Which is a correct 'Expected result' statement?",["a:It should work","b:The page should load the dashboard within 2 seconds","c:The bug should not appear","d:Everything should be fine"],"b","'Expected result' harus spesifik dan bisa diukur. 'It should work' tidak menjelaskan APA yang seharusnya terjadi. Pilihan B menyebutkan halaman mana, tindakan apa, dan berapa lama."),
      mcq(`${pid}_04`,"'Actual result' in a bug report should describe:",["a:What you think the cause is","b:Exactly what happens, including error messages and codes","c:What should happen","d:The fix you recommend"],"b","'Actual result' adalah observasi TEPAT tentang apa yang terjadi — termasuk pesan error, kode HTTP, dan perilaku yang terlihat. Bukan teori, bukan saran — hanya fakta yang diamati."),
      mcq(`${pid}_05`,"Which is the best one-sentence incident summary?",["a:There was an outage.","b:The system was down for a while today.","c:The payment API was unavailable from 14:02 to 16:47 UTC on 2026-05-10, affecting 1,200 transactions.","d:We had some problems with the payments."],"c","Ringkasan insiden yang baik menjawab dalam satu kalimat: APA (payment API), KAPAN (14:02–16:47 UTC), TANGGAL (2026-05-10), dan DAMPAK (1,200 transactions). Pilihan A, B, D terlalu samar."),
      mcq(`${pid}_06`,"A root cause statement should be:",["a:Blame-focused: 'Developer X pushed a breaking change'","b:Technical and factual: 'The connection pool was exhausted due to a missing retry timeout configuration'","c:Vague: 'Something went wrong with the config'","d:Focused on who was on-call"],"b","Root cause = penjelasan teknis yang faktual tentang apa yang gagal dan mengapa. Bukan menyalahkan orang, bukan samar-samar — harus spesifik dan bisa menjadi dasar pencegahan."),
      mcq(`${pid}_07`,"'Impact' in an incident report should NOT include:",["a:Number of users affected","b:Revenue or SLA breach","c:The name of the engineer who caused it","d:Affected services"],"c","Incident report fokus pada FAKTA TEKNIS: berapa pengguna terdampak, layanan apa yang terpengaruh, apakah ada pelanggaran SLA. Nama individu yang 'menyebabkan' tidak boleh masuk karena post-mortem harus blameless."),
      mcq(`${pid}_08`,"Which tense is most appropriate for a bug report 'Steps to Reproduce' section?",["a:Past tense: 'I clicked the button'","b:Present simple imperative: 'Click the button'","c:Future tense: 'You will click the button'","d:Past perfect: 'I had clicked the button'"],"b","Langkah reproduksi menggunakan present simple imperative (kata perintah): Click, Enter, Navigate, Press. Ini standar universal yang membuat langkahnya terasa seperti instruksi yang bisa diikuti siapapun kapanpun."),
      mcq(`${pid}_09`,"'Prevention' section of an incident report should contain:",["a:A list of people to blame","b:Specific action items with owners and due dates","c:General advice like 'be more careful'","d:A promise to do better"],"b","Bagian pencegahan harus KONKRET: tindakan apa, siapa yang bertanggung jawab, dan kapan deadlinenya. 'Be more careful' tidak bisa diukur dan tidak mencegah insiden serupa."),
      mcq(`${pid}_10`,"In a Jira bug report, 'severity' and 'priority' are different because:",["a:They mean the same thing","b:Severity = technical impact; priority = business urgency","c:Severity = who caused it; priority = who fixes it","d:Priority = technical impact; severity = business urgency"],"b","Severity = seberapa parah dampak teknisnya (P1 crash semua user vs P3 UI glitch kecil). Priority = seberapa mendesak harus diperbaiki dari sisi bisnis. Bug bisa severity rendah tapi priority tinggi karena klien VIP."),
      mcq(`${pid}_11`,"Which phrase best starts a timeline entry in an incident report?",["a:At some point,","b:14:02 UTC — Alert fired: auth service returning 503.","c:Then the system crashed.","d:Around lunchtime,"],"b","Entri timeline harus pakai TIMESTAMP yang tepat (UTC) dan deskripsi faktual singkat. 'At some point' dan 'Around lunchtime' tidak cukup presisi untuk investigasi."),
      mcq(`${pid}_12`,"When a bug is 'intermittent', the steps to reproduce should:",["a:Be omitted since the bug can't be reproduced","b:Include frequency, conditions, and what was observed when it occurred","c:Just say 'it happens randomly'","d:Be replaced with a video only"],"b","Bug intermiten tetap harus didokumentasikan: seberapa sering terjadi (1 dari 10 kali?), kondisi apa yang ada saat terjadi, dan apa yang terlihat. 'It happens randomly' tidak berguna untuk engineer yang akan memperbaikinya."),
      mcq(`${pid}_13`,"'The developer pushed bad code' in a root cause — this is:",["a:A good, specific root cause","b:Blame language — focus on the technical failure, not the person","c:Acceptable in formal reports","d:The correct format"],"b","Root cause analysis harus BLAMELESS — fokus pada kegagalan sistem, proses, atau konfigurasi, bukan pada orangnya. Menyalahkan individu mencegah orang jujur dan tidak membantu pencegahan."),
      mcq(`${pid}_14`,"In a post-mortem, 'Lessons Learned' should be:",["a:A list of complaints about the process","b:Specific, actionable items linked to what went wrong","c:General reflections with no owners","d:An optional section"],"b","'Lessons Learned' harus spesifik dan terhubung langsung dengan apa yang salah. Bukan keluhan umum, bukan tanpa pemilik — harus bisa diimplementasikan dan diverifikasi."),
      mcq(`${pid}_15`,"Which environment detail is most useful in a bug report?",["a:The developer's laptop model","b:Browser: Chrome 124, OS: macOS 14.5, App version: 3.2.1, Environment: staging","c:Time of day the bug was found","d:How frustrated the user was"],"b","Detail lingkungan yang berguna untuk engineer: browser dan versinya, OS, versi aplikasi, dan environment (staging/production). Tanpa ini, engineer tidak tahu di mana harus mencari masalahnya."),
      mcq(`${pid}_16`,"An incident report's 'Resolution' section should describe:",["a:What caused the incident","b:What action restored normal service, and when","c:What the team will do next month","d:How many users complained"],"b","Bagian resolusi menjelaskan: tindakan SPESIFIK apa yang dilakukan untuk memulihkan layanan, dan kapan layanan normal kembali. Ini berbeda dari root cause (penyebab) dan prevention (pencegahan)."),
      mcq(`${pid}_17`,"Which phrase is most appropriate for a post-mortem root cause section?",["a:The team was not paying attention.","b:A misconfigured health check endpoint caused the load balancer to route traffic to an unresponsive node.","c:There was a problem with the server.","d:Someone deleted the wrong file."],"b","Root cause terbaik: spesifik secara teknis (health check endpoint salah konfigurasi), gunakan passive voice (caused by, resulted in), dan blameless. Pilihan B jelas apa yang salah dan mengapa dampaknya terjadi."),
      mcq(`${pid}_18`,"'Evidence' in a bug report should include:",["a:Your opinion of the code quality","b:Error logs, stack traces, screenshots, HTTP response codes","c:Team member names","d:Future improvement suggestions"],"b","Bukti harus bisa DIVERIFIKASI: log error, stack trace, screenshot, kode HTTP. Opini tentang kualitas kode bukan bukti — itu adalah penilaian subjektif yang tidak membantu reproduksi bug."),
      mcq(`${pid}_19`,"When filing a P1 (critical) bug, your first action should be:",["a:File the Jira ticket and wait","b:Immediately notify the on-call engineer and file the ticket simultaneously","c:Write a detailed root cause analysis first","d:Email the CEO"],"b","P1 (critical) = lakukan DUA HAL bersamaan: notifikasi on-call engineer LANGSUNG (jangan tunggu) dan buat ticket. Jangan tunggu ticket selesai dulu baru kasih tahu — setiap detik penting."),
      mcq(`${pid}_20`,"Which is a measurable 'impact' statement?",["a:Many users were affected.","b:The service was slow.","c:Approximately 800 users were unable to complete checkout for 47 minutes, resulting in an estimated $12,000 in lost revenue.","d:Performance was degraded."],"c","Dampak harus TERUKUR: jumlah pengguna, durasi, dan konsekuensi bisnisnya. Pilihan C memberikan semua ini. 'Many users' dan 'slow' tidak bisa menjadi dasar keputusan bisnis."),
      mcq(`${pid}_21`,"A bug report with no 'Steps to Reproduce' is problematic because:",["a:It takes longer to read","b:Engineers cannot verify the bug or test the fix","c:It looks unprofessional","d:Jira requires this field"],"b","Tanpa langkah reproduksi, engineer tidak bisa memverifikasi bug ada, tidak bisa menguji apakah fix-nya berhasil, dan tidak bisa memastikan tidak muncul lagi. Bug report tanpa repro steps hampir tidak berguna."),
      mcq(`${pid}_22`,"In a bug report, 'Actual result' should be written:",["a:After the developer confirms the bug","b:Only if you can reproduce the issue","c:With exact error messages, behaviour observed, and screenshots where relevant","d:As a one-word description"],"c","'Actual result' = deskripsi PRESISI berbasis bukti: pesan error yang tepat, perilaku yang terlihat, dan screenshot kalau relevan. Ini yang engineer gunakan untuk memahami masalahnya."),
      mcq(`${pid}_23`,"A post-mortem is 'blameless' because:",["a:No one was at fault","b:Focusing on systemic failures leads to better prevention than assigning blame","c:It is HR policy","d:Engineers should not be held accountable"],"b","Blameless bukan berarti tidak ada yang bertanggung jawab — tapi fokus pada KEGAGALAN SISTEM, bukan pada orangnya. Ini menciptakan budaya di mana orang jujur dan insiden bisa dicegah lebih efektif."),
      mcq(`${pid}_24`,"Which is the best 'Resolution' statement?",["a:We fixed it.","b:The on-call engineer restarted the pod.","c:The degraded pod was identified at 14:50 UTC and terminated; traffic was rerouted to healthy instances by 14:53 UTC, restoring full service.","d:The problem went away."],"c","Resolusi terbaik: tindakan spesifik (pod diidentifikasi dan dihentikan), timestamp akurat, dan konfirmasi pemulihan (traffic rerouted, full service restored). Pilihan A dan D tidak informatif sama sekali."),
      mcq(`${pid}_25`,"After filing a bug report, you should:",["a:Close the ticket immediately","b:Monitor for updates, respond to developer questions, and verify the fix in the relevant environment","c:Reassign it to someone else","d:Delete it if it is not fixed within a day"],"b","Pelapor bug bertanggung jawab sampai selesai: pantau update, jawab pertanyaan developer, dan VERIFIKASI fix-nya di environment yang relevan. Menutup ticket sebelum diverifikasi bisa menyebabkan bug yang sama kembali."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`Title: The dashboard\nSteps: Open the app. Do stuff. It crashes.\nExpected: Should work.\nActual: Doesn't work.`,`Title: Dashboard crashes on load when user has >500 notifications\nSteps:\n1. Log in as a user with 500+ unread notifications.\n2. Navigate to /dashboard.\nExpected: Dashboard loads within 2 seconds.\nActual: Application crashes with 'Maximum call stack exceeded' error in console.`,"All bug report fields must be specific and actionable."))
      else if(pn<=7) drills.push(fill(id,`**Summary**: The checkout service ___ unavailable from 09:15 to 11:42 UTC on 2026-05-12, ___ approximately 450 transactions and resulting in a 2-hour SLA breach.`,["was","affecting"],"Incident summary: past passive for status; present participle for impact."))
      else if(pn===8) drills.push(write(id,`Write a professional bug report title (max 15 words) for this scenario:\nUsers cannot reset their password if they signed up with Google OAuth. The reset link sends but the page returns a 403 error.`,20))
      else if(pn===9) drills.push(write(id,`Write a complete bug report for this scenario:\nThe API returns incorrect pagination data when the page size parameter exceeds 100. Results duplicate from the previous page. Affects the mobile app and dashboard. Environment: production v2.3.1.`,150))
      else drills.push(write(id,`Write a 5-sentence post-mortem summary for this incident:\nThe production database was accidentally dropped during a migration script run on staging (which had production credentials). Service was down for 3 hours. 2,000 users affected. Data was restored from backup.`,130))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 3 · Day 3 ── Status Updates & Meeting Communication ───────────── */

const W3D3=mk(3,3,
  "Status Updates & Meeting Communication",
  "Communicate progress, blockers, and plans clearly in standups, sprint reviews, and written updates.",
  "Status update yang baik itu harus bisa menjawab tiga pertanyaan dalam 30 detik: Apa yang sudah selesai? Apa yang sedang dikerjakan? Ada hambatan apa?\n\n**Format standup (Kemarin / Hari ini / Hambatan)**:\n- Kemarin: 'I completed [task] and reviewed [PR].' (spesifik, bukan 'I worked on stuff')\n- Hari ini: 'I'm working on [task] and will start [task].' (ada komitmen yang jelas)\n- Hambatan: 'I'm blocked on [masalah spesifik]. I need [hal spesifik] from [nama orang] by [waktu].'\n\n**Update status tertulis**:\n- Mulai dengan label status: on track / at risk / blocked.\n- Gunakan angka persentase atau jumlah tugas yang spesifik, bukan kata-kata yang samar.\n- Sebutkan dampak dari setiap hambatan ke sprint goal.\n\n**Samar vs. Tepat**:\n- Samar: 'Things are going okay, maybe done soon.' (tidak berguna untuk tim)\n- Tepat: 'API integration is 70% complete. Estimated completion: Thursday EOD.' (jelas dan bisa ditindaklanjuti)\n\n**Cara melaporkan hambatan (4 langkah)**:\n1. Sebutkan apa yang terhambat.\n2. Sebutkan mengapa terhambat.\n3. Sebutkan apa yang dibutuhkan dan dari siapa.\n4. Sebutkan dampaknya kalau tidak diselesaikan sebelum [tanggal].",
  gp("w3d3",(pid,pn)=>{
    const TITLES=["Standup Language MCQ","Status Precision MCQ","Blocker Communication MCQ","Sprint Review Language","Meeting Facilitation Language","Fill — Standup Update","Fill — Written Status","Write a Standup Update","Write a Blocker Escalation","Speak: Full Sprint Update"]
    const OBJS=["Identify correct standup format and professional language.","Choose precise status language over vague hedging.","Communicate blockers with specificity and proposed resolution.","Use appropriate language for sprint review presentations.","Facilitate meetings with clear, professional language.","Complete standup update templates correctly.","Complete written status report templates.","Write a full 3-part standup update for a realistic scenario.","Write a formal blocker escalation with impact statement.","Speak: deliver a full sprint review update aloud."]
    const m=[
      mcq(`${pid}_01`,"In a standup, 'I'll try to finish the feature today' sounds:",["a:Professional and realistic","b:Hedging — replace with a specific deliverable or flag as at-risk","c:Too confident","d:Appropriately modest"],"b","Di standup, kita perlu memberikan komitmen yang jelas — atau terus terang bilang 'at risk'. Kata 'try' artinya belum pasti. Tim tidak bisa mengandalkan sesuatu yang hanya 'dicoba'. Lebih baik bilang: 'I will finish the login feature by EOD' ATAU 'The login feature is at risk — I need design assets first.'"),
      mcq(`${pid}_02`,"'Things are going well' in a status update should be replaced with:",["a:Nothing — it's concise","b:A specific milestone or percentage: 'Sprint is 75% complete; 9 of 12 tickets done'","c:'Everything is fine'","d:'No updates at this time'"],"b","Update status harus pakai ANGKA, bukan kata samar. '75% complete, 9 dari 12 tiket selesai' jauh lebih berguna dari 'things are going well' — tim bisa langsung hitung sendiri apakah sprint bisa selesai tepat waktu atau tidak."),
      mcq(`${pid}_03`,"The best way to raise a blocker in a standup is:",["a:'I'm stuck.'","b:'I'm blocked on the payment gateway integration. I need the API keys from ops by noon today — otherwise the sprint goal is at risk.'","c:'There are some issues.'","d:'Can someone help me later?'"],"b","Blocker yang baik menjawab 4 hal: APA yang terhambat, MENGAPA terhambat, APA yang dibutuhkan dan dari SIAPA, dan KAPAN dibutuhkan beserta DAMPAKNYA. 'I'm stuck' tidak menjawab satu pun dari itu — tim tidak tahu harus membantu apa."),
      mcq(`${pid}_04`,"'I'm going to try to look at the PR today if I get time' in a standup means:",["a:The PR will be reviewed today","b:The PR review is not a committed task — flag it honestly","c:The PR has been reviewed","d:The task is blocked"],"b","Kalau kamu bilang 'if I get time' di standup, artinya kamu TIDAK berkomitmen. Lebih jujur untuk bilang 'PR review is not in my plan for today — I have higher priority tasks' daripada memberi harapan palsu yang kemudian tidak ditepati."),
      mcq(`${pid}_05`,"Which status is most useful in a written sprint update?",["a:On track","b:Making progress","c:At risk — DB migration is 2 days behind schedule due to environment setup delays. Revised completion: 2026-05-15.","d:Almost done"],"c","Update status yang berguna harus bisa ditindaklanjuti. 'At risk' saja kurang — tapi 'At risk — 2 hari terlambat karena masalah environment setup, selesai 15 Mei' memberi tim informasi konkret untuk mengambil keputusan: apakah perlu bantu, apakah perlu ubah scope, atau perlu eskalasi."),
      mcq(`${pid}_06`,"When facilitating a meeting, 'Let's take this offline' means:",["a:Shut down the topic permanently","b:Continue this discussion outside the meeting with the relevant people","c:The topic is resolved","d:You disagree with the speaker"],"b","'Take this offline' artinya kita lanjutkan diskusi ini DI LUAR rapat, hanya dengan orang-orang yang relevan. Ini cara sopan untuk bilang: 'topik ini terlalu spesifik untuk dibahas di sini — sebaiknya kita bicara terpisah agar rapat tidak terganggu.'"),
      mcq(`${pid}_07`,"'We're in the weeds' in a meeting means:",["a:The team is working efficiently","b:The discussion has become too detailed or lost focus","c:The project is complete","d:There is a blocker"],"b","'In the weeds' adalah idiom bahasa Inggris yang artinya 'terjebak dalam detail yang terlalu banyak sampai kehilangan arah'. Bayangkan berjalan di ladang dan gulma terlalu tinggi sehingga kamu tidak bisa melihat ke mana harus pergi — begitulah diskusi yang terlalu detail."),
      mcq(`${pid}_08`,"Which sprint review opening is most effective?",["a:'Hi everyone, today we're going to talk about what we did.'","b:'This sprint we delivered three features: user authentication, payment integration, and the admin dashboard. Demo follows.'","c:'We worked hard this sprint.'","d:'There's a lot to cover today.'"],"b","Buka sprint review dengan ringkasan KONKRET: apa yang berhasil dikirim. Ini langsung memberi konteks kepada semua hadirin. Kalimat seperti 'we worked hard' tidak memberi informasi apa pun — semua orang sudah tahu kerja keras itu, yang mereka ingin tahu adalah HASILNYA."),
      mcq(`${pid}_09`,"'We should circle back on this' means:",["a:The topic is resolved","b:Return to this topic later or in a follow-up","c:You disagree","d:End the meeting"],"b","'Circle back' artinya 'kita kembali ke topik ini nanti' — di pertemuan berikutnya atau secara async. Ini cara profesional untuk mengatakan 'kita tunda dulu, tapi tidak dilupakan'. Bayangkan seperti menaruh bookmark di halaman buku — akan dibuka lagi, tapi bukan sekarang."),
      mcq(`${pid}_10`,"When a meeting is going off-topic, a professional facilitator should say:",["a:'Stop talking about irrelevant things.'","b:'Let's park this for now and add it to the next agenda — we have limited time today.'","c:Nothing — let the conversation flow","d:'This is boring.'"],"b","'Park this' artinya mencatat topik itu untuk dibahas nanti, tapi tidak sekarang. Cara ini menjaga rapat tetap fokus sekaligus memastikan topik tersebut tidak hilang. Bayangkan seperti 'parking lot' — topiknya diparkir dulu, bukan dibuang."),
      mcq(`${pid}_11`,"In a standup, what does 'no blockers' mean?",["a:Everything is perfect","b:There are no current impediments to your planned work today","c:The sprint is ahead of schedule","d:You don't need help"],"b","'No blockers' artinya tidak ada hambatan untuk pekerjaan yang DIRENCANAKAN hari ini — bukan berarti semua sempurna. Kalau ada masalah kecil tapi tidak menghambat pekerjaan hari ini, kamu boleh tetap bilang 'no blockers'."),
      mcq(`${pid}_12`,"'Action item' in a meeting context is:",["a:A topic for discussion","b:A specific task assigned to a person with a deadline","c:A complaint","d:A feature request"],"b","'Action item' adalah TUGAS yang harus dikerjakan — bukan sekadar topik yang didiskusikan. Setiap action item harus punya tiga elemen: TUGAS apa, SIAPA yang bertanggung jawab, dan KAPAN harus selesai. Tanpa ketiganya, kemungkinan besar tidak akan selesai."),
      mcq(`${pid}_13`,"Which is the clearest way to report sprint velocity?",["a:We did pretty well","b:We completed 38 story points out of 42 committed, achieving 90% velocity","c:We almost hit our target","d:We did most of the sprint"],"b","Sprint velocity diukur dengan ANGKA yang spesifik: berapa story points yang selesai dibanding yang dikomitmenkan. '38 dari 42 poin = 90% velocity' jauh lebih jelas dan berguna untuk perencanaan sprint berikutnya daripada 'we did pretty well'."),
      mcq(`${pid}_14`,"In a retrospective, 'What went well' should include:",["a:Vague praise: 'We worked hard'","b:Specific practices: 'Our daily code reviews caught 4 bugs before they reached staging'","c:Only negative feedback","d:Individual performance ratings"],"b","Di retrospektif, 'what went well' harus spesifik dan terhubung ke PRAKTIK tertentu agar bisa diulangi. 'Daily code review menangkap 4 bug sebelum ke staging' = bisa diulangi dan dikembangkan. 'We worked hard' = tidak bisa ditindaklanjuti sama sekali."),
      mcq(`${pid}_15`,"When you say 'I'll pick this up' in a meeting, you mean:",["a:You will take on the task","b:You will attend the next meeting","c:You will escalate the issue","d:You need more information"],"a","'I'll pick this up' artinya SAYA yang akan mengerjakan tugas ini — saya mengambil tanggung jawabnya (ownership). Ini ungkapan yang menunjukkan inisiatif dan proaktif dalam tim. Kebalikannya adalah menunggu seseorang menugaskan kamu."),
      mcq(`${pid}_16`,"'LGTM' in a code review comment means:",["a:Let's Get Technical, Mate","b:Looks Good To Me — approval","c:Let me Get This Merged","d:Let's Go To Main"],"b","LGTM adalah singkatan dari 'Looks Good To Me' — artinya kode sudah diperiksa dan disetujui untuk di-merge. Ini singkatan standar dalam code review di hampir semua tim engineering dunia. Kalau kamu lihat LGTM di PR kamu, artinya reviewer sudah setuju!"),
      mcq(`${pid}_17`,"Which is the best way to decline taking on a task in a standup?",["a:'That's not my job.'","b:'I'm at capacity this sprint — could we assign this to someone with bandwidth, or defer it?'","c:'No.'","d:'Why are you asking me?'"],"b","Cara profesional untuk menolak tambahan pekerjaan adalah: sebutkan alasannya (kapasitas penuh), lalu tawarkan solusi alternatif (assign ke orang lain yang punya bandwidth, atau defer ke sprint berikutnya). Jangan hanya bilang 'tidak' tanpa konteks atau solusi."),
      mcq(`${pid}_18`,"A 'parking lot' in a meeting is:",["a:A break area","b:A list of topics noted but not discussed during the meeting, for follow-up","c:A place to put rejected ideas","d:A voting mechanism"],"b","'Parking lot' dalam rapat adalah daftar topik-topik yang muncul tapi tidak bisa dibahas sekarang karena keterbatasan waktu atau di luar scope. Topik-topik ini dicatat agar tidak hilang dan bisa dibahas di lain waktu. Bukan dibuang — hanya 'diparkir' sementara."),
      mcq(`${pid}_19`,"Which is the best 'Yesterday' standup item?",["a:'I worked on stuff.'","b:'I completed the user profile API (ticket ENG-234) and reviewed two PRs.'","c:'I was busy.'","d:'I did a lot.'"],"b","Item 'Yesterday' di standup harus spesifik: tugas apa yang SELESAI, nomor tiketnya berapa, dan statusnya. 'I worked on stuff' tidak memberi informasi yang berguna — tim tidak tahu apakah pekerjaanmu selesai, sedang berjalan, atau terhambat."),
      mcq(`${pid}_20`,"'Bandwidth' in a workplace context means:",["a:Internet speed","b:Available time or capacity to take on work","c:Server throughput","d:Team size"],"b","Di tempat kerja, 'bandwidth' BUKAN berarti kecepatan internet — artinya KAPASITAS atau waktu yang tersedia untuk mengerjakan sesuatu. 'Do you have bandwidth for this?' artinya 'Apakah kamu punya waktu/kapasitas untuk mengerjakan ini sekarang?'"),
      mcq(`${pid}_21`,"Which sprint goal statement is most effective?",["a:Complete all the tickets","b:Ship the payment feature to production by Friday so the marketing campaign can launch","c:Do our best","d:Work on backend tasks"],"b","Sprint goal yang baik berbasis HASIL (outcome) dan terhubung ke nilai bisnis — bukan sekadar daftar aktivitas. 'Ship payment feature so the marketing campaign can launch' = jelas dampaknya ke bisnis. 'Complete all tickets' = hanya daftar kegiatan tanpa makna yang lebih besar."),
      mcq(`${pid}_22`,"'Deliverable' vs 'task' — what is the difference?",["a:They are the same","b:Deliverable = the tangible output; task = the work done to produce it","c:Deliverable = task list; task = outcome","d:Neither has a standard meaning"],"b","Deliverable adalah HASIL yang bisa dilihat atau dipakai — produk akhirnya. Task adalah KEGIATAN untuk menghasilkan deliverable itu. Contoh mudah: task = 'menulis dokumentasi API', deliverable = 'dokumen API yang sudah jadi dan bisa dibaca developer lain'."),
      mcq(`${pid}_23`,"In a sprint review, who should present completed work?",["a:Only the manager","b:The team member who did the work — it builds accountability and communication skills","c:Only the PM","d:No one — just demo it silently"],"b","Di sprint review, anggota tim yang mengerjakan fitur itulah yang mempresentasikannya — bukan manager atau PM. Ini membangun rasa tanggung jawab (accountability) atas pekerjaan sendiri dan melatih kemampuan komunikasi teknis yang sangat penting di dunia kerja."),
      mcq(`${pid}_24`,"Which blocker description needs the most improvement?",["a:I'm blocked on ENG-234 because the staging database credentials are missing. I need ops to provide them by 14:00 today.","b:I'm stuck.","c:The auth service is returning 401s in staging — I need Sam to check the OAuth config before I can proceed.","d:I'm waiting on design approval for the new modal — expected by tomorrow EOD."],"b","'I'm stuck' adalah blocker terburuk yang bisa dilaporkan. Tidak ada konteks (apa yang terhambat?), tidak ada penyebab (kenapa?), tidak ada permintaan (butuh apa dari siapa?). Tim tidak tahu harus membantu seperti apa. Bandingkan dengan pilihan A, C, D yang semuanya memberi informasi yang bisa ditindaklanjuti."),
      mcq(`${pid}_25`,"Meeting minutes should include:",["a:Every word that was said","b:Decisions made, action items (with owners and dates), and topics deferred","c:Only the fun parts","d:Attendance list only"],"b","Notulen rapat yang baik mencatat tiga hal penting: KEPUTUSAN yang diambil, ACTION ITEMS (dengan penanggung jawab dan deadline), dan TOPIK yang ditunda. Bukan transkrip lengkap percakapan — cukup poin-poin yang bisa ditindaklanjuti setelah rapat selesai."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`Yesterday: I was working on stuff.\nToday: I'll try to continue.\nBlockers: Some issues maybe.`,`Yesterday: I completed the database schema migration for ENG-301 and merged PR #47.\nToday: I will implement the API endpoints for user profile update (ENG-302).\nBlockers: None currently.`,"Standup items must be specific, committed, and clear."))
      else if(pn<=7) drills.push(fill(id,`Sprint status: At ___. The feature development is ___ % complete with 3 of 5 API endpoints delivered. The remaining 2 endpoints are ___ on the third-party OAuth approval, expected by Wednesday.`,["risk","60","blocked"],"Status update: status label, percentage, and specific blocker."))
      else if(pn===8) drills.push(write(id,`Write a full standup update (Yesterday / Today / Blockers) for this scenario:\nYesterday you fixed a login bug (JIRA-415) and code-reviewed two PRs. Today you plan to start the email notification feature (JIRA-420). You are waiting for design assets from the UX team, needed by EOD today.`,80))
      else if(pn===9) drills.push(write(id,`Write a formal written blocker escalation message to your tech lead:\nYou are blocked on the payment integration because the Stripe API credentials for staging have not been provided. You have asked the ops team twice (Monday and Wednesday). The sprint goal (payment feature in staging by Friday) is now at risk.`,100))
      else drills.push(speak(id,"Speak for 90 seconds: present your sprint progress as if in a sprint review. Cover: what was committed, what was delivered, what was not completed and why, and what the team will focus on next sprint."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 3 · Day 4 ── Technical Documentation ───────────────────────────── */

const W3D4=mk(3,4,
  "Technical Documentation & Explanations",
  "Write clear README sections, API docs, technical specs, and plain-language explanations for mixed audiences.",
  "Dokumentasi teknis yang baik itu seperti peta wisata — siapapun yang membacanya harus bisa sampai ke tujuan tanpa perlu bertanya ke penulisnya.\n\n**Elemen penting README**: Gambaran umum (1 kalimat), prasyarat, instalasi, penggunaan, referensi API, panduan kontribusi.\n\n**Struktur dokumentasi API**:\n- Endpoint: method + path (contoh: GET /users/{id})\n- Deskripsi: apa yang dilakukan endpoint ini\n- Parameter: nama, tipe, wajib/opsional, deskripsi\n- Contoh permintaan (request example)\n- Contoh respons dengan kode status HTTP\n- Kode error dan artinya\n\n**Prinsip penulisan teknis**:\n1. **Bahasa sederhana**: pilih kata yang mudah dipahami, terutama untuk pembaca non-teknis.\n2. **Active voice**: 'Call the endpoint', bukan 'The endpoint should be called'.\n3. **Konsisten**: gunakan istilah yang sama sepanjang dokumen (jangan berganti antara 'user' dan 'customer').\n4. **Contoh konkret**: tunjukkan dengan contoh, jangan hanya jelaskan.\n5. **Present tense** untuk mendeskripsikan perilaku sistem: 'The API **returns** a JSON object.'\n\n**Menjelaskan ke pemangku kepentingan non-teknis**: gunakan analogi dari kehidupan sehari-hari, hindari jargon teknis, fokus pada DAMPAKNYA ke bisnis bukan cara kerjanya secara teknis.",
  gp("w3d4",(pid,pn)=>{
    const TITLES=["Technical Writing Style MCQ","API Documentation Language","Audience-Appropriate Language","README Structure MCQ","Active vs. Passive Voice","Fill — API Description","Fill — README Section","Write an API Endpoint Description","Write a Non-Technical Explanation","Write a Technical Spec Section"]
    const OBJS=["Evaluate technical writing for clarity and correctness.","Use precise, standard API documentation language.","Adjust technical language for technical and non-technical audiences.","Evaluate README structure and completeness.","Choose active voice for instructions; passive for system facts.","Complete an API parameter description correctly.","Complete a README installation section correctly.","Write a complete API endpoint description.","Explain a technical concept to a non-technical stakeholder.","Write a technical specification section for a new feature."]
    const m=[
      mcq(`${pid}_01`,"Which technical documentation style is clearest?",["a:The endpoint will return a JSON object containing user data when it is called correctly.","b:Returns a JSON object with user profile data.","c:This is used to get user data.","d:You should use this to get user stuff."],"b","Dokumentasi teknis yang baik: pakai present tense ('Returns', bukan 'will return'), langsung ke intinya (tidak perlu kalimat panjang), dan spesifik (sebutkan tipe datanya: JSON object, bukan hanya 'stuff'). Bayangkan dokter yang menulis resep — harus jelas dan ringkas, tidak berputar-putar."),
      mcq(`${pid}_02`,"'Prerequisites' in a README should list:",["a:Nice-to-have tools","b:Required software, versions, and dependencies with installation links","c:The author's preferences","d:Optional configuration"],"b","'Prerequisites' artinya SYARAT WAJIB — bukan yang bagus kalau ada. Bayangkan resep masak: kalau kamu tidak punya tepung, kamu tidak bisa mulai. Begitu juga README — developer harus tahu versi Node.js yang dibutuhkan, library apa yang harus diinstall dulu, dan di mana mendapatkannya."),
      mcq(`${pid}_03`,"Which is the most appropriate way to document an error code?",["a:Error 403 — bad request","b:403 Forbidden — The API key does not have permission to access this resource.","c:Something went wrong","d:Don't use this if you get an error"],"b","Error code yang baik menyebutkan: kode HTTP (403), nama resminya (Forbidden), dan KAPAN/KENAPA error ini terjadi. Developer yang menemukan error 403 harus langsung tahu apa yang salah — jangan biarkan mereka menebak-nebak."),
      mcq(`${pid}_04`,"When explaining a database to a non-technical manager, you should say:",["a:It's a relational database with ACID-compliant transactions.","b:It's where all the user information is stored — think of it as the app's filing system.","c:It uses B-tree indexes for fast lookups.","d:It runs PostgreSQL 15 with read replicas."],"b","Untuk audiens non-teknis, gunakan ANALOGI dari kehidupan sehari-hari dan fokus pada APA YANG DILAKUKAN, bukan bagaimana caranya. 'Filing system' adalah analogi yang sempurna — semua orang tahu cara kerja lemari arsip. Detail teknis seperti 'ACID' atau 'B-tree index' hanya akan membingungkan."),
      mcq(`${pid}_05`,"'Call the API with the user token in the Authorization header' vs 'The Authorization header should be populated with the user token' — which is better for developer docs?",["a:The second — more formal","b:The first — active, direct instruction","c:Neither — both are wrong","d:Both are equally good"],"b","Untuk instruksi di dokumentasi developer, gunakan kalimat perintah aktif (imperative active voice): 'Call', 'Set', 'Include' — langsung dan jelas. Kalimat pasif seperti 'should be populated' terdengar lebih formal tapi lebih lambat dipahami saat developer sedang mencari solusi cepat."),
      mcq(`${pid}_06`,"A 'required' vs 'optional' parameter distinction in API docs is important because:",["a:It looks professional","b:Developers need to know what must be included to avoid 400 errors","c:It is Swagger convention only","d:Optional parameters are never used"],"b","Kalau developer tidak tahu mana parameter yang wajib (required), mereka akan mendapat error 400 Bad Request dan membuang waktu mencari tahu apa yang salah. Dokumentasi yang jelas = lebih sedikit frustrasi = developer lebih produktif."),
      mcq(`${pid}_07`,"Which README installation section is best?",["a:Install everything and run it.","b:Clone the repo, install dependencies, set env vars, and run.\n```\ngit clone ...\nnpm install\ncp .env.example .env\nnpm run dev\n```","c:You'll figure it out.","d:See the main file."],"b","Bagian instalasi README yang baik: langkah yang BERURUTAN (numbered steps), instruksi yang SPESIFIK, dan CONTOH KODE yang bisa langsung dicopy-paste. Tujuannya: developer baru harus bisa menjalankan proyekmu dalam 5 menit tanpa perlu bertanya."),
      mcq(`${pid}_08`,"Technical specifications should be written in:",["a:Future tense: 'The system will store user data'","b:Present tense for behavior: 'The system stores user data'; future for not-yet-built: 'The system will support OAuth2'","c:Past tense throughout","d:Whichever feels natural"],"b","Aturan tense di technical spec: Present tense ('The system stores') untuk perilaku yang SUDAH ADA sekarang, Future tense ('The system will support') untuk fitur yang BELUM DIBANGUN. Ini membantu pembaca langsung tahu mana yang sudah jalan dan mana yang masih rencana."),
      mcq(`${pid}_09`,"Inline code comments should:",["a:Explain WHAT the code does","b:Explain WHY the code does something non-obvious","c:Be written for every line","d:Be avoided entirely"],"b","Komentar kode yang baik menjelaskan MENGAPA — bukan APA. Nama fungsi dan variabel yang bagus sudah menjelaskan APA yang dilakukan kode. Yang tidak bisa dijelaskan oleh nama adalah alasan di balik keputusan yang tidak obvious. Contoh: // Using setTimeout(0) to yield to browser event loop — ini 'why' yang berguna."),
      mcq(`${pid}_10`,"When writing a technical explanation for a non-technical client, you should:",["a:Use all technical terms so they trust your expertise","b:Define every acronym, use analogies, and focus on business impact","c:Write in the same way as for engineers","d:Keep it extremely short with no explanation"],"b","Untuk klien non-teknis: jelaskan setiap singkatan, gunakan analogi sehari-hari, dan fokus pada DAMPAK KE BISNIS — bukan cara kerjanya secara teknis. Klien tidak perlu tahu cara kerja mesin mobil; mereka perlu tahu berapa lama perjalanannya dan berapa biayanya."),
      mcq(`${pid}_11`,"Which API description is most complete?",["a:GET /users","b:GET /users — Returns a paginated list of active users. Supports 'limit' (default 20, max 100) and 'cursor' parameters for pagination.","c:Get users from the database.","d:Users endpoint."],"b","Deskripsi API yang lengkap mencakup: method + path (GET /users), APA yang dikembalikan (paginated list of active users), dan PARAMETER UTAMA yang didukung beserta nilai defaultnya. Developer harus bisa memahami cara pakai endpoint ini hanya dari deskripsi singkat ini."),
      mcq(`${pid}_12`,"'Consistent terminology' in technical docs means:",["a:Using the same font","b:Always using the same term for the same concept (e.g., always 'user', never alternating with 'customer')","c:Using formal language throughout","d:Avoiding abbreviations"],"b","Konsistensi terminologi berarti selalu pakai kata yang SAMA untuk konsep yang sama di seluruh dokumen. Kalau kamu mulai dengan 'user', jangan berganti ke 'customer' atau 'member' di paragraf berikutnya. Pergantian kata yang tidak perlu membuat pembaca bertanya-tanya: 'apakah ini hal yang berbeda?'"),
      mcq(`${pid}_13`,"A changelog entry should:",["a:List every file that changed","b:State the version, date, and what changed in user-facing terms: Added, Changed, Fixed, Removed, Deprecated","c:Include the full git diff","d:Be written only for major versions"],"b","Changelog yang baik mencatat: versi + tanggal + apa yang berubah dalam bahasa yang dimengerti pengguna (Added, Changed, Fixed, Removed, Deprecated). Bukan list file yang berubah — pengguna tidak peduli file mana yang diubah, mereka peduli FITUR mana yang bertambah atau bug mana yang diperbaiki."),
      mcq(`${pid}_14`,"When writing a 'Getting Started' guide, you should:",["a:Assume the reader has full expertise","b:Start from zero: environment setup, first run, and a working example within 5 minutes","c:Point them to the source code","d:List all features before explaining how to start"],"b","'Getting Started' yang baik dimulai dari NOL dan punya satu tujuan: developer baru harus punya contoh yang BERJALAN dalam 5 menit. Jangan listing semua fitur dulu — langsung tunjukkan cara menjalankannya. Kepuasan awal ('it works!') membuat developer mau terus eksplorasi."),
      mcq(`${pid}_15`,"Diagrams in technical docs should:",["a:Replace all written explanations","b:Supplement text by showing system relationships, data flow, or architecture that is hard to describe in prose","c:Be decorative only","d:Only be used in slide decks"],"b","Diagram berguna untuk menjelaskan HUBUNGAN dan ALIRAN yang sulit dijelaskan dengan kata-kata — seperti arsitektur sistem, data flow, atau sequence diagram. Tapi diagram MELENGKAPI teks, bukan menggantikannya. Teks memberi detail; diagram memberi gambaran besar."),
      mcq(`${pid}_16`,"Which is the best way to document a 'breaking change'?",["a:Bury it in the middle of the changelog","b:Clearly mark it with BREAKING CHANGE at the top of the release notes with a migration guide","c:Mention it only in the commit message","d:Don't document it — users will figure it out"],"b","Breaking change adalah perubahan yang akan MERUSAK kode yang sudah ada. Ini harus ditandai dengan jelas di bagian paling atas release notes (bukan dikubur di tengah), plus panduan migrasi. Bayangkan jalan tol yang tiba-tiba ganti arah — kamu perlu rambu besar, bukan catatan kecil di sudut."),
      mcq(`${pid}_17`,"'Returns 200 OK with the user object' vs 'Returns the user' — which is better in API docs?",["a:The second — shorter","b:The first — includes HTTP status code and response type","c:Both are equally good","d:Neither — only show code examples"],"b","Dokumentasi API response harus menyebutkan KODE STATUS HTTP (200, 201, 404, dll) dan TIPE RESPONSE-nya. Developer perlu tahu dua hal: apakah request berhasil (200 OK) dan apa yang mereka terima (user object). 'Returns the user' terlalu samar — user dalam bentuk apa?"),
      mcq(`${pid}_18`,"A technical specification document should begin with:",["a:The complete implementation details","b:An overview: problem, proposed solution, scope, and out of scope","c:A list of all API endpoints","d:Team member names"],"b","Technical spec yang baik dimulai dengan gambaran besar dulu: masalah apa yang diselesaikan, solusi yang diusulkan, dan apa yang masuk/tidak masuk scope. Ini penting untuk menyamakan pemahaman semua stakeholder SEBELUM masuk ke detail implementasi."),
      mcq(`${pid}_19`,"'Out of scope' in a technical spec is important because:",["a:It makes the document longer","b:It explicitly states what will not be built, preventing scope creep","c:It is always optional","d:It is only for the product team"],"b","'Out of scope' adalah salah satu bagian TERPENTING dalam technical spec. Dengan secara eksplisit menyebut apa yang TIDAK akan dibangun, kita mencegah 'scope creep' — yaitu kebiasaan menambah-nambah fitur di tengah jalan yang membuat proyek molor dan membengkak."),
      mcq(`${pid}_20`,"Which is the best explanation of 'caching' for a non-technical client?",["a:It uses Redis with an LRU eviction policy and a 5-minute TTL.","b:It saves frequently requested information temporarily so pages load faster — like keeping a book open on the right page instead of fetching it from the shelf every time.","c:It optimises throughput by reducing database I/O.","d:It's a technical thing that makes performance better."],"b","Analogi membuat konsep teknis mudah dipahami siapa saja. 'Menyimpan buku terbuka di halaman yang sering dibuka' adalah analogi sempurna untuk caching — semua orang mengerti konsep ini. Detail teknis seperti Redis, LRU eviction, atau TTL hanya relevan untuk engineer, bukan klien."),
      mcq(`${pid}_21`,"In API documentation, 'Rate limiting' should be described as:",["a:Don't call the API too much","b:Max 100 requests per minute per API key. Exceeding this returns 429 Too Many Requests with a Retry-After header.","c:Limited usage","d:Call less if there are errors"],"b","Dokumentasi rate limit harus sangat spesifik: BERAPA banyak request (100 per menit per API key), APA yang terjadi kalau melebihi batas (error 429 Too Many Requests), dan BAGAIMANA cara menanganinya (gunakan Retry-After header). Tanpa angka spesifik, developer tidak bisa merancang implementasinya."),
      mcq(`${pid}_22`,"A CONTRIBUTING.md file should include:",["a:The team's salaries","b:How to set up the dev environment, coding standards, branch naming, PR process, and how to run tests","c:Only the PR template","d:Marketing copy"],"b","CONTRIBUTING.md adalah panduan untuk developer yang ingin berkontribusi ke proyekmu. Harus mencakup: cara setup environment, standar koding yang diharapkan, konvensi nama branch, proses PR (review, approval), dan cara menjalankan test. Tanpa ini, kontributor baru tidak tahu harus mulai dari mana."),
      mcq(`${pid}_23`,"When updating documentation after a code change, you should:",["a:Update the docs in the same PR as the code","b:Create a separate documentation PR a week later","c:Not update docs for minor changes","d:Wait for users to report the outdated docs"],"a","Dokumentasi harus diupdate di PR yang SAMA dengan perubahan kodenya. Ini memastikan kode dan dokumentasi selalu sinkron. Kalau dipisah ke PR terpisah, ada risiko lupa update, atau ada orang lain yang merge kodenya tapi dokumentasinya belum diupdate — dan hasilnya adalah dokumentasi yang menyesatkan."),
      mcq(`${pid}_24`,"'Type: string (required)' in an API parameter description tells the developer:",["a:Nothing useful","b:The data type and that omitting it will cause an error","c:Only the type — required is obvious","d:Only that it is required"],"b","'Type: string (required)' memberikan dua informasi penting sekaligus: TIPE DATA yang harus dikirim (string, bukan number atau boolean) dan WAJIB/TIDAK (kalau tidak dikirim, request akan gagal dengan error 400). Ini informasi minimum yang dibutuhkan developer untuk memanggil API dengan benar."),
      mcq(`${pid}_25`,"Technical documentation that is never updated is:",["a:Better than no documentation","b:Potentially worse than no documentation — outdated docs mislead and waste developer time","c:Fine if the fundamentals don't change","d:Still useful regardless"],"b","Dokumentasi yang tidak pernah diupdate bisa LEBIH BERBAHAYA dari tidak ada dokumentasi sama sekali. Mengapa? Karena developer akan mengikuti instruksi yang salah dengan penuh keyakinan — dan itu membuang waktu lebih banyak daripada kalau mereka harus eksplorasi dari awal. Dokumentasi usang = jebakan tersembunyi."),
    ]
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=4) drills.push(m[i%m.length])
      else if(pn===5) drills.push(fix(id,`GET /api/users/{id}\n\nThis is used to get user information. You need an id. Returns stuff.`,`GET /api/users/{id}\n\n**Returns** the profile of the specified user.\n\n**Parameters**:\n- \`id\` (string, required) — The unique user ID.\n\n**Response**: 200 OK with a user object. 404 if the user does not exist.`,"API docs need endpoint + description + parameters + response codes."))
      else if(pn<=7) drills.push(fill(id,`___ the repository, install ___, and copy the environment file before running the development server.`,["Clone","dependencies"],"README imperative instructions."))
      else if(pn===8) drills.push(write(id,`Write a complete API endpoint description for:\nPOST /api/sessions — creates a new user session. Requires: email (string), password (string). Returns: session token (string) and expiry (ISO timestamp). Errors: 400 if fields missing, 401 if credentials invalid.`,100))
      else if(pn===9) drills.push(write(id,`Explain to a non-technical project manager (in plain English, no jargon) what a 'database migration' is and why it sometimes causes downtime. Use an analogy.`,80))
      else drills.push(write(id,`Write the 'Overview' and 'Scope' section of a technical spec for: adding two-factor authentication (2FA) to the existing login system. Include what will and will not be built in this phase.`,120))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

/* ── Week 3 · Day 5 ── Week 3 Review ────────────────────────────────────── */

const W3D5=mk(3,5,
  "Week 3 Review — Professional Writing",
  "Apply email, report, status, and documentation writing skills in integrated professional scenarios.",
  "**Panduan cepat — ringkasan Week 3**:\n- Email: subjek spesifik, pembuka langsung, permintaan yang jelas + deadline, penutup profesional. Jangan kubur permintaanmu di paragraf ke-3!\n- Bug report: judul tepat (komponen + perilaku), langkah bernomor dengan kata perintah, hasil yang diharapkan vs aktual, bukti (log/screenshot), dampak.\n- Update status: sebutkan label status duluan (on track/at risk/blocked), progress yang terukur (angka/persentase), hambatan spesifik + dampaknya.\n- Dokumentasi: active voice untuk instruksi, present tense untuk perilaku sistem, contoh konkret, istilah yang konsisten sepanjang dokumen.",
  gp("w3d5",(pid,pn)=>{
    const TITLES=["Email Quality MCQ","Bug Report Language","Status Communication","Documentation Review","Mixed Writing MCQ","Fix — Email","Fix — Bug Report","Write: Request Email","Write: Incident Summary","Speak: Team Presentation"]
    const OBJS=Array.from({length:10},(_,i)=>`Apply Week 3 professional writing skills in realistic IT scenarios — phase ${i+1}.`)
    const drills:Drill[]=[]
    for(let i=0;i<25;i++){
      const id=`${pid}_${String(i+1).padStart(2,"0")}`
      if(pn<=2) drills.push(mcq(id,`Which is the most professional written status update? #${i+1}`,["a:Things are going fine.","b:Sprint is on track: 7/10 tickets complete. The checkout feature (ENG-112) is 80% done — estimated completion: Friday EOD.","c:We're almost there!","d:Working hard on it."],"b","Update status yang baik harus bisa dijawab dalam satu pandangan: statusnya apa (on track), progressnya berapa (7/10 tiket), detail spesifik apa (ENG-112 di 80%), dan kapan selesai (Friday EOD). Semua info itu ada di pilihan B. Pilihan lain terlalu samar untuk bisa ditindaklanjuti oleh tim atau manager."))
      else if(pn<=4) drills.push(fill(id,`**Subject**: Production ___ — checkout API returning 500 errors since 14:00 UTC\n\nDear team,\n\nI am writing to ___ you of a critical issue affecting the checkout service. Approximately ___ users are unable to complete purchases. I am currently investigating and will provide an update within 30 minutes.`,["incident","inform","300"],"Incident email: subject, formal opener, impact numbers."))
      else if(pn<=6) drills.push(fix(id,`Yesterday: stuff.\nToday: more stuff.\nBlockers: things are complicated.`,`Yesterday: Completed the authentication module refactor (ENG-198) and reviewed 3 PRs.\nToday: Begin integration testing for the payment gateway (ENG-204).\nBlockers: Awaiting Stripe test credentials from ops — blocking ENG-204. Need by EOD today.`,"Standup: specific tasks, ticket numbers, specific blocker with deadline."))
      else if(pn<=8) drills.push(write(id,`Write a professional email to the product team requesting a scope clarification meeting.\nContext: The requirements for the notification feature are ambiguous — you need to know whether push notifications should be real-time or batched before you can begin development. The deadline is next Monday.`,120))
      else if(pn===9) drills.push(write(id,`Write a one-paragraph post-mortem incident summary:\nThe user authentication service went down for 22 minutes (10:15–10:37 UTC on 2026-05-13) due to an expired SSL certificate. Approximately 1,400 users were affected. The certificate was renewed and services restored. Prevention: automated certificate renewal added.`,100))
      else drills.push(speak(id,"Speak for 2 minutes: you are presenting your team's work to a non-technical stakeholder. Cover: what was built this sprint, one problem you encountered and how you solved it, and what you plan to deliver next sprint."))
    }
    return{id:pid,phaseNumber:pn,title:TITLES[pn-1],objective:OBJS[pn-1],drills}
  })
)

export const WEEK3_DAYS: DayPlan[] = [W3D1, W3D2, W3D3, W3D4, W3D5]
